9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	  moonstone: 25,
34	};
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_PREMIUM = 60;
38	
39	/** Items that share the same `type`, and so are priced together. */
40	type AlikeItems = { type: string; items: Item[] };
41	
42	const groupByType = (items: Item[]): AlikeItems[] => {
43	  const itemsByType = new Map<string, Item[]>();
44	  for (const item of items) {
45	    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
46	  }
47	  return [...itemsByType].map(([type, alike]) => ({ type, items: alike }));
48	};
49	
50	const formsBlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
51	
52	const basePremiumFor = ({ type, items }: AlikeItems): number =>
53	  formsBlock(items) ? BLOCK_PREMIUM : items.length * BASE_PREMIUMS[type];
54	
55	const totalBasePremium = (items: Item[]): number =>
56	  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);
57	
58	const quotePremium = (items: Item[]): number => {
59	  const base = totalBasePremium(items);
60	  // Keep the surcharge additive (base + base * rate). The algebraically
61	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
62	  // which Math.ceil turns into a premium that is 1 G too high.
63	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
64	  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
65	};
66	
67	export const runScenario = (scenario: Scenario): Result[] =>
68	  scenario.steps.map((step) => {
69	    if (step.op === "quote") return { premium: quotePremium(step.items) };
70	    throw new Error(`Unsupported step: ${step.op}`);
71	  });
