const formsBlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const basePremiumFor = ({ items }: AlikeItems): number =>
  formsBlock(items)
    ? BLOCK_PREMIUM
    : items.reduce((total, item) => total + itemBasePremium(item), 0);

